mapper.select:
select r.*, u.user_name, d.dept_name, s.shift_name
from hr_attendance_result r
left join sys_user u on u.user_id = r.user_id
left join sys_dept d on d.dept_id = r.dept_id
left join hr_shift s on s.shift_id = r.shift_id

    1=1
    and r.user_id = #{userId}
    and date_format(r.work_date, '%Y-%m') = #{params.month}
    and r.work_date >= #{params.beginDate}
    and r.work_date <= #{params.endDate}

order by r.work_date desc, r.user_id
